# Check Paley(29) for K_5 and independent set of size 5
q = 29
residues = set()
for x in range(1, q):
    residues.add((x*x) % q)

# Build adjacency matrix
adj = [[0]*q for _ in range(q)]
for i in range(q):
    for j in range(q):
        if i != j:
            diff = (i - j) % q
            if diff in residues:
                adj[i][j] = 1

# Check for K_5 (clique of size 5)
import itertools

found_clique = False
for combo in itertools.combinations(range(q), 5):
    ok = True
    for i in range(5):
        for j in range(i+1, 5):
            if adj[combo[i]][combo[j]] == 0:
                ok = False
                break
        if not ok:
            break
    if ok:
        print("Found K_5:", combo)
        found_clique = True
        break

if not found_clique:
    print("No K_5 in Paley(29)")

