# Build the full edge list for K_22 using Paley(29) coloring
q = 29
residues = set()
for x in range(1, q):
    residues.add((x*x) % q)

n = 22
result = []
for i in range(n):
    for j in range(i+1, n):
        diff = (i - j) % q
        if diff in residues:
            result.append(0)  # red
        else:
            result.append(1)  # blue

print("Result list:", result)
print("Length:", len(result))
